"""Independent verifier for version-3 controller results (development tool)."""
import json, math, sys
from fractions import Fraction
from collections import deque
sys.path.insert(0, '/workspace/vendor')
sys.path.insert(0, '/workspace/submission')
import probability, metrics, testcnnonnx, testrnnonnx


def build(case, values, eligible):
    slots = case['slots']; windows = case['windows']; flows = case['flows']; groups = case['groups']
    B, I = case['bucket']
    S = len(slots); J = len(windows); F = len(flows); G = len(groups)
    a = lambda s: 2+3*s
    b = lambda s: 3+3*s
    e = lambda s: 4+3*s
    w = lambda j: 2+3*S+j
    z = lambda f: 2+3*S+J+f
    h = lambda g: 2+3*S+J+F+g
    K = 2+3*S+J+F+G
    W = 1 + J*slots[-1][0]
    arcs = []
    pair_pos = {}
    for s in range(S):
        arcs.append((0, a(s), 0, I if s == 0 else slots[s][2], 0))
        arcs.append((a(s), b(s), 0, B, 0))
        if s+1 < S: arcs.append((b(s), a(s+1), 0, B, 0))
        arcs.append((b(s), e(s), 0, slots[s][1], 0))
    for s in range(S):
        for j in range(J):
            if eligible[j] and windows[j][1] <= slots[s][0] <= windows[j][2]:
                pair_pos[(s, j)] = len(arcs)
                arcs.append((e(s), w(j), 0, 1, (slots[s][0]-windows[j][1]) - values[j]*W))
    for j in range(J):
        arcs.append((w(j), z(windows[j][0]), 0, 1, 0))
    flow_pos = {}
    for f in range(F):
        dest = h(flows[f][2]) if flows[f][2] >= 0 else 1
        flow_pos[f] = len(arcs)
        arcs.append((z(f), dest, 0, flows[f][1], 0))
    for g in range(G):
        dest = h(groups[g][0]) if groups[g][0] >= 0 else 1
        arcs.append((h(g), dest, 0, groups[g][1], 0))
    arcs.append((1, 0, 0, J, 0))
    return arcs, K, W, pair_pos, flow_pos


def max_flow(n, edges, s, t, limit):
    """Independent (Edmonds-Karp) max flow; edges are [u, v, cap] lists."""
    adj = [[] for _ in range(n)]
    to = [0]*(2*len(edges)); cap = [0]*(2*len(edges))
    for i, e in enumerate(edges):
        u, v, c = e
        adj[u].append(2*i); adj[v].append(2*i+1)
        to[2*i] = v; cap[2*i] = c
        to[2*i+1] = u; cap[2*i+1] = 0
    flow = 0
    while flow < limit:
        parent = [-1]*n; parent[s] = -2
        q = deque([s])
        while q and parent[t] == -1:
            u = q.popleft()
            for e in adj[u]:
                if cap[e] > 0 and parent[to[e]] == -1:
                    parent[to[e]] = e; q.append(to[e])
                    if to[e] == t: break
        if parent[t] == -1: break
        d = limit - flow; v = t
        while v != s:
            e = parent[v]; d = min(d, cap[e]); v = to[e ^ 1]
        v = t
        while v != s:
            e = parent[v]; cap[e] -= d; cap[e ^ 1] += d; v = to[e ^ 1]
        flow += d
    return flow


def feasible(case, L, arcs, K, flow_pos, F):
    """Feasibility of the lower bounded circulation with the given lowers."""
    S = len(case['slots']); J = len(case['windows'])
    s, t = K, K+1
    edges = []
    for i, (u, v, lo, hi, c) in enumerate(arcs):
        edges.append([u, v, max(0, hi-lo)])
    dests = {}
    for f in range(F):
        dests[arcs[flow_pos[f]][1]] = dests.get(arcs[flow_pos[f]][1], 0) + L[f]
    for dest, amount in dests.items():
        edges.append([s, dest, amount])
    for f in range(F):
        edges.append([2+3*S+J+f, t, L[f]])
    demand = sum(L)
    got = max_flow(K+2, edges, s, t, demand)
    return got == demand, got, demand


def check_case(case, result):
    problems = []
    windows = case['windows']; flows = case['flows']; groups = case['groups']; slots = case['slots']
    B, I = case['bucket']
    S = len(slots); J = len(windows); F = len(flows); G = len(groups)
    feats = [w[7] for w in windows]
    labels = [0]*J
    if case['model'] == 'cnn':
        preds = testcnnonnx.evaluate_model_single_pass(feats, labels)
    else:
        preds = testrnnonnx.evaluate_model_single_pass(feats, labels)
    if list(preds) != list(result['predictions']): problems.append('predictions mismatch')
    thr = probability.window_thresholds(case['stats'], windows)
    if list(thr) != list(result['thresholds']): problems.append('thresholds mismatch')
    values = [windows[j][6]*case['class_values'][result['predictions'][j]] for j in range(J)]
    eligible = [windows[j][5] < result['thresholds'][j] for j in range(J)]
    arcs, K, W, pair_pos, flow_pos = build(case, values, eligible)
    assignment = list(result['assignment'])
    if len(assignment) != J: problems.append('assignment length')
    used = [0]*S; counts = [0]*F
    for j, s in enumerate(assignment):
        if s < 0: continue
        if not eligible[j]: problems.append('ineligible window assigned'); continue
        if not (windows[j][1] <= slots[s][0] <= windows[j][2]): problems.append('outside ready/expires')
        used[s] += 1; counts[windows[j][0]] += 1
    for s in range(S):
        if used[s] > slots[s][1]: problems.append('slot capacity exceeded')
    inv = I
    for s in range(S):
        if s > 0: inv = min(B, inv + slots[s][2])
        if used[s] > inv: problems.append('token budget exceeded at slot %d' % s)
        inv -= used[s]
    for f in range(F):
        if counts[f] > flows[f][1]: problems.append('flow ceiling exceeded')
    def ancestors(g):
        out = []
        while g != -1: out.append(g); g = groups[g][0]
        return out
    for anc in range(G):
        tot = sum(counts[ff] for ff in range(F) if flows[ff][2] != -1 and anc in ancestors(flows[ff][2]))
        if tot > groups[anc][1]: problems.append('group ceiling exceeded')
    u = sum(values[j] for j, s in enumerate(assignment) if s >= 0)
    a = sum(slots[s][0]-windows[j][1] for j, s in enumerate(assignment) if s >= 0)
    if u != result['utility']: problems.append('utility mismatch')
    if a != result['age']: problems.append('age mismatch')
    cov = Fraction(1)
    for f in range(F): cov = min(cov, Fraction(counts[f], flows[f][0]))
    p, q = result['ratio']
    if Fraction(p, q) != cov: problems.append('ratio mismatch %s vs %s' % (result['ratio'], cov))
    flow = list(result['flow'])
    if len(flow) != len(arcs):
        problems.append('flow length')
        return problems
    Lf = [math.ceil(cov*flows[f][0]) for f in range(F)]
    for i, (u2, v2, lo, hi, c) in enumerate(arcs):
        if flow[i] < lo or flow[i] > hi: problems.append('flow out of bounds arc %d' % i)
    for (s, j), pos in pair_pos.items():
        want = 1 if assignment[j] == s else 0
        if flow[pos] != want: problems.append('pair arc mismatch (%d,%d)' % (s, j))
    net = [0]*K
    for i, (u2, v2, lo, hi, c) in enumerate(arcs):
        net[u2] -= flow[i]; net[v2] += flow[i]
    for node in range(K):
        if net[node] != 0: problems.append('conservation node %d (%d)' % (node, net[node]))
    pot = list(result['potential'])
    if len(pot) != K: problems.append('potential length')
    else:
        for i, (u2, v2, lo, hi, c) in enumerate(arcs):
            x = flow[i]
            if x < hi and c + pot[u2] - pot[v2] < 0: problems.append('potential fwd arc %d' % i)
            if x > lo and -c + pot[v2] - pot[u2] < 0: problems.append('potential bwd arc %d' % i)
            if abs(pot[u2]) > 10**60: problems.append('potential magnitude')
    cands = set()
    for f in range(F):
        for k in range(flows[f][0]+1): cands.add(Fraction(k, flows[f][0]))
    nxt = min([c for c in cands if c > cov], default=None)
    if cov < 1:
        if result['cut'] is None: problems.append('cut missing')
        else:
            inside = set(result['cut'])
            if len(inside) != len(result['cut']): problems.append('cut duplicates')
            if not inside <= set(range(K)): problems.append('cut node range')
            inc = 0; outc = 0
            for i, (u2, v2, lo, hi, c) in enumerate(arcs):
                lo2 = 0
                for f in range(F):
                    if flow_pos[f] == i: lo2 = math.ceil(nxt*flows[f][0])
                if v2 in inside and u2 not in inside: inc += lo2
                elif u2 in inside and v2 not in inside: outc += hi
            if not inc > outc: problems.append('cut condition %d <= %d' % (inc, outc))
    else:
        if result['cut'] is not None: problems.append('cut should be null')
    # maximality: r+ must be infeasible, r must be feasible
    if nxt is not None:
        Lnext = [math.ceil(nxt*flows[f][0]) for f in range(F)]
        ok, got, dem = feasible(case, Lnext, arcs, K, flow_pos, F)
        if ok: problems.append('next ratio %s is feasible -> coverage not maximal' % nxt)
    Lnow = [math.ceil(cov*flows[f][0]) for f in range(F)]
    ok, got, dem = feasible(case, Lnow, arcs, K, flow_pos, F)
    if not ok: problems.append('reported coverage not feasible')
    rep = metrics.selected_report(flows, windows, list(result['predictions']), assignment)
    if json.dumps(rep, sort_keys=True) != json.dumps(result['reports'], sort_keys=True):
        problems.append('reports mismatch')
    return problems


def main():
    request = json.loads(open(sys.argv[1]).read())
    response = json.loads(open(sys.argv[2]).read())
    if 'error' in response:
        print('ERROR response:', response); return 1
    assert response['version'] == 3
    bad = 0
    for index, (case, result) in enumerate(zip(request['cases'], response['results'])):
        problems = check_case(case, result)
        if problems:
            bad += 1
            print('case %d: %s' % (index, '; '.join(problems)))
    print('checked %d cases, %d with problems' % (len(request['cases']), bad))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
